<div class="dashboard-heading"><div><span class="eyebrow">SUAS COMPRAS</span><h2>Meus pedidos</h2><p>O pedido principal reúne os subpedidos de cada loja.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Data</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><strong><?= e($order['code']) ?></strong></td><td><?= date('d/m/Y',strtotime($order['created_at'])) ?></td><td>R$ <?= number_format((float)$order['grand_total'],2,',','.') ?></td><td><?php $status=$order['status']; require dirname(__DIR__,2).'/components/dashboard/status-badge.php'; ?></td><td><a href="<?= e(url('/minha-conta/pedidos/'.$order['code'])) ?>">Detalhes</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$orders): $emptyTitle='Você ainda não fez pedidos'; require dirname(__DIR__,2).'/components/dashboard/empty-state.php'; endif; ?></div></section>
